use std :: collections :: HashMap ; use derive_more :: { Deref , From } ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use serde_json :: Value ; use crate :: { Attachment , NamedTool , Template , TerminalContext , ToolName } ; use super :: * ; impl EventContext { pub fn new (event : impl Into < EventContextValue >) -> Self { Self { event : event . into () , suggestions : Default :: default () , variables : Default :: default () , current_date : chrono :: Local :: now () . format ("%Y-%m-%d") . to_string () , terminal_context : None , } } # [doc = " Converts this EventContext into a feedback event by setting the event"] # [doc = " name to \"feedback\". This should be used when the context already"] # [doc = " contains user messages."] pub fn into_feedback (mut self) -> Self { self . event . name = "feedback" . to_string () ; self } # [doc = " Converts this EventContext into a new task event by setting the event"] # [doc = " name to \"task\". This should be used when this is a new task without"] # [doc = " prior user messages."] pub fn into_task (mut self) -> Self { self . event . name = "task" . to_string () ; self } }